-- Fakt kartochkalarining ruscha matni — 26-partiya: adiblar.
-- Berdaq, Sadriddin Ayniy, Mirtemir, Odil Yoqubov, Pirimqul Qodirov,
-- Shukur Xolmirzayev, Tog'ay Murod, Muhammad Yusuf.

-- ===== Berdaq =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Бердах?', fact_ru = 'Я родился в 1827 году в Муйнакском районе Каракалпакстана, в семье рыбака.' WHERE id = 2007;
UPDATE fact_cards SET topic_ru = 'Моё настоящее имя', question_ru = 'Каким было настоящее имя Бердаха?', fact_ru = 'Моё настоящее имя — Бердимурад, а отца моего звали Каргабай. В народе я стал известен под именем Бердах.' WHERE id = 2008;
UPDATE fact_cards SET topic_ru = 'Школа и медресе', question_ru = 'Где учился Бердах?', fact_ru = 'Сперва я учился в аульной школе, затем в медресе. Но окончить учение в медресе я не смог и вынужден был его оставить.' WHERE id = 2009;
UPDATE fact_cards SET topic_ru = 'Домбра и моё творчество', question_ru = 'Как начиналось творчество Бердаха?', fact_ru = 'С 18–19 лет я начал играть на домбре и слагать стихи. А в 25 лет я стал известен в народе как одарённый поэт.' WHERE id = 2010;
UPDATE fact_cards SET topic_ru = 'Мои дастаны', question_ru = 'Автором каких дастанов является Бердах?', fact_ru = 'Я написал дастаны «Родословная», «Хорезм», «Амангельды», «Айдос-бий» и «Царь-глупец».' WHERE id = 2011;
UPDATE fact_cards SET topic_ru = 'Мои стихи и мои темы', question_ru = 'Какие стихи писал Бердах и какие темы он в них освещал?', fact_ru = 'Я написал такие стихи, как «Для народа», «Подать», «Придёт ли лето», «Не бывало», «Лучше». В них я воспевал жизнь народа, говорил о гнёте и несправедливости, о тяжести податей.' WHERE id = 2012;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Бердах и когда его стихи были изданы на узбекском языке?', fact_ru = 'Я скончался в 1900 году. После моей смерти, в 1961 году, сборник моих стихов был издан на узбекском языке.' WHERE id = 2013;

-- ===== Sadriddin Ayniy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Садриддин Айни?', fact_ru = 'Я родился в 1878 году в Гиждуванском районе Бухарской области. Моё настоящее имя — Садриддин Саидмурадзаде, а «Айни» — мой литературный псевдоним.' WHERE id = 2282;
UPDATE fact_cards SET topic_ru = 'Моя учёба в медресе', question_ru = 'Где учился Садриддин Айни?', fact_ru = 'Сперва, в 1884–1887 годах, я учился в старой школе. Затем я учился в бухарских медресе — Мир-Араб (1890–91), Алимхана (1892–93), Бадалбека (1894–96), Ходжи Захида (1896–99) и Кукельдаш (1899–1900).' WHERE id = 2283;
UPDATE fact_cards SET topic_ru = 'Школы нового метода', question_ru = 'Что делал Айни в деле образования?', fact_ru = 'Я открывал в Бухаре школы нового метода и создавал для них учебные пособия. В 1909 году я составил учебник «Воспитание молодёжи» и деятельно участвовал в движении «младобухарцев». На моё мировоззрение заметно повлияли труды Ахмада Дониша и просветителей-джадидов.' WHERE id = 2284;
UPDATE fact_cards SET topic_ru = 'Моё творчество на двух языках', question_ru = 'На каких языках творил Айни?', fact_ru = 'Я творил на двух языках — узбекском и таджикском. На таджикском я написал роман «Дохунда» (1927–29), а на узбекском — роман «Рабы» (1934).' WHERE id = 2285;
UPDATE fact_cards SET topic_ru = 'Мой роман «Рабы»', question_ru = 'Когда Айни написал роман «Рабы»?', fact_ru = 'В 1934 году я написал на узбекском языке свой роман «Рабы». Кроме того, я создал повести «Бухарские палачи» (1922), «Старая школа» (1935) и сатирическую повесть «Смерть ростовщика» (1939).' WHERE id = 2286;
UPDATE fact_cards SET topic_ru = 'Мой труд «Воспоминания»', question_ru = 'О чём труд «Воспоминания»?', fact_ru = 'В 1949–1954 годах я написал свой труд «Воспоминания», состоящий из четырёх частей. В нём я отразил прошлую жизнь Бухары.' WHERE id = 2287;
UPDATE fact_cards SET topic_ru = 'Моя научная работа', question_ru = 'Какие научные труды создал Айни?', fact_ru = 'Я писал научные труды по истории литературы: создал исследования о Фирдоуси, Рудаки, Саади и Алишере Навои. Я дал сведения более чем о 200 поэтах, историках и учёных из тысячелетней истории таджикской и узбекской литератур. В 1948 году я стал доктором филологических наук, в 1950 году — профессором.' WHERE id = 2288;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Садриддин Айни?', fact_ru = 'В последние годы жизни, начиная с 1951 года, я работал первым президентом Академии наук Таджикистана. Я скончался в 1954 году.' WHERE id = 2289;

-- ===== Mirtemir =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Миртемир?', fact_ru = 'Я родился 30 мая 1910 года в селении Икан близ города Туркестан. Моё полное имя — Миртемир Турсунов.' WHERE id = 2227;
UPDATE fact_cards SET topic_ru = 'Где я учился', question_ru = 'Где учился Миртемир?', fact_ru = 'Сперва я учился в старой школе, затем в образцовой школе имени Альмаи в Ташкенте. А в 1925–1929 годах я учился в Узбекском мужском училище.' WHERE id = 2228;
UPDATE fact_cards SET topic_ru = 'Моя первая книга', question_ru = 'Как называется первая книга Миртемира?', fact_ru = 'В 1928 году я издал свою первую книгу под названием «В объятиях лучей». Этот мой сборник написан в жанре свободного стиха.' WHERE id = 2229;
UPDATE fact_cards SET topic_ru = 'Моя поэма «Портрет»', question_ru = 'Что за произведение «Портрет» Миртемира?', fact_ru = 'Одно из самых знаменитых моих произведений — лирическая повесть «Портрет», я написал её в 1956–1957 годах в Каракалпакстане. Это моё произведение сильно повлияло на становление жанра лирической поэмы в узбекской поэзии.' WHERE id = 2230;
UPDATE fact_cards SET topic_ru = 'Мои поэмы', question_ru = 'Какие поэмы написал Миртемир?', fact_ru = 'Я написал такие поэмы, как «Барат», «Хидыр», «Дилькушо», «Дочь воды», «На свадьбе Ойсанам» и «Кузи». Я выпустил и поэтические сборники «Победа», «Мои кипения» и «Набат».' WHERE id = 2231;
UPDATE fact_cards SET topic_ru = 'Мои переводы', question_ru = 'Какие произведения переводил Миртемир?', fact_ru = 'Я перевёл на узбекский язык стихи Пушкина, поэму Некрасова «Кому на Руси жить хорошо» и поэму Руставели «Витязь в тигровой шкуре». Переложил я и киргизский народный эпос «Манас», и произведения Абая, Махтумкули и Бердаха.' WHERE id = 2232;
UPDATE fact_cards SET topic_ru = 'Моё звание народного поэта', question_ru = 'Какие звания и награды получил Миртемир?', fact_ru = 'В 1971 году я получил звание «Народный поэт Узбекистана». А в 1977 году удостоился Государственной премии Каракалпакстана имени Бердаха.' WHERE id = 2233;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Миртемир?', fact_ru = 'Я скончался 25 января 1978 года в городе Ташкенте. Всю свою жизнь я посвятил поэзии и переводческому делу.' WHERE id = 2234;

-- ===== Odil Yoqubov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Адыл Якубов?', fact_ru = 'Я родился 20 октября 1926 года в селении Карнак нынешней Южно-Казахстанской области.' WHERE id = 2243;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'Где учился Адыл Якубов?', fact_ru = 'В 1956 году я окончил филологический факультет Ташкентского государственного университета.' WHERE id = 2244;
UPDATE fact_cards SET topic_ru = 'Моё первое произведение', question_ru = 'Каково первое произведение Адыла Якубова?', fact_ru = 'Моё первое произведение — повесть «Ровесники» — было напечатано в 1951 году. Затем я написал произведения «Первый шаг» (1953) и «Мукаддас» (1960).' WHERE id = 2245;
UPDATE fact_cards SET topic_ru = 'Мой роман «Сокровищница Улугбека»', question_ru = 'Кто написал роман «Сокровищница Улугбека»?', fact_ru = 'Одно из самых знаменитых моих произведений — роман «Сокровищница Улугбека» — было издано в 1973 году. А в 1982 году я написал свой роман «Древний мир».' WHERE id = 2246;
UPDATE fact_cards SET topic_ru = '«Совесть» и другие мои романы', question_ru = 'Какие романы написал Адыл Якубов?', fact_ru = 'В 1977 году был издан мой роман «Совесть». Кроме того, я написал романы «Если беда придёт на голову...» (1966), «Лебеди, белые лебеди» (1988) и «Обитель справедливости» (1998).' WHERE id = 2247;
UPDATE fact_cards SET topic_ru = 'Мои награды', question_ru = 'Какие награды получил Адыл Якубов?', fact_ru = 'В 1977 году я удостоился Государственной премии имени Хамзы, а в 1985 году мне было присвоено звание «Народный писатель Узбекистана». В 1994 году я был награждён орденом «Дустлик», в 1998 году — орденом «Эль-юрт хурмати».' WHERE id = 2248;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Адыл Якубов?', fact_ru = 'Я скончался 21 декабря 2009 года в городе Ташкенте.' WHERE id = 2249;

-- ===== Pirimqul Qodirov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Пиримкул Кадыров?', fact_ru = 'Я родился 25 октября 1928 года в селении Кенгкуль Шахристанского района нынешней Республики Таджикистан.' WHERE id = 2258;
UPDATE fact_cards SET topic_ru = 'Годы моей учёбы', question_ru = 'Где учился Пиримкул Кадыров?', fact_ru = 'В 1951 году я окончил факультет востоковедения Среднеазиатского университета. В том же 1951 году я напечатал и свой первый рассказ «Студенты».' WHERE id = 2259;
UPDATE fact_cards SET topic_ru = 'Мой роман «Звёздные ночи»', question_ru = 'О ком написан роман «Звёздные ночи»?', fact_ru = 'В 1979 году я издал свой роман «Звёздные ночи». Это произведение посвящено жизни великого поэта и государственного деятеля Захириддина Мухаммада Бабура.' WHERE id = 2260;
UPDATE fact_cards SET topic_ru = '«Перевал поколений»', question_ru = 'Что за произведение роман «Перевал поколений»?', fact_ru = 'В 1989 году я издал свой роман «Перевал поколений». Он является продолжением моего романа «Звёздные ночи».' WHERE id = 2261;
UPDATE fact_cards SET topic_ru = 'Мои другие произведения', question_ru = 'Какие ещё произведения написал Пиримкул Кадыров?', fact_ru = 'Я написал романы «Три корня» (1958), «Чёрные глаза» (1966) и «Алмазный пояс» (1976), а также произведения «Моё достоинство» (1961) и «Воля» (1968). В 2000 году было издано моё произведение «Клич матери-сокола».' WHERE id = 2262;
UPDATE fact_cards SET topic_ru = 'Моя научная работа', question_ru = 'Какую научную работу вёл Пиримкул Кадыров?', fact_ru = 'Я работал и как учёный-литературовед: в 1963–1983 годах я был старшим научным сотрудником Института языка и литературы Академии наук Узбекистана. Я написал такие научные труды, как «Язык и сердце» (1972).' WHERE id = 2263;
UPDATE fact_cards SET topic_ru = 'Мои награды', question_ru = 'Какие награды получил Пиримкул Кадыров?', fact_ru = 'В 1988 году мне было присвоено звание народного писателя Узбекистана. Я также был награждён Государственной премией имени Хамзы (1981), медалью «Шухрат» (1994) и орденом «Эль-юрт хурмати» (1998).' WHERE id = 2264;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Пиримкул Кадыров?', fact_ru = 'Я скончался в 2010 году.' WHERE id = 2265;

-- ===== Shukur Xolmirzayev =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Шукур Холмирзаев?', fact_ru = 'Я родился 24 марта 1940 года в Байсунском районе Сурхандарьинской области. Байсун — моя родина.' WHERE id = 2322;
UPDATE fact_cards SET topic_ru = 'Годы моей учёбы', question_ru = 'Где учился Шукур Холмирзаев?', fact_ru = 'Мои первые рассказы и очерки начали печататься с 1958 года. В 1963 году я окончил факультет журналистики Ташкентского университета.' WHERE id = 2323;
UPDATE fact_cards SET topic_ru = 'Мои первые произведения', question_ru = 'Каковы первые произведения Шукура Холмирзаева?', fact_ru = 'Моя первая повесть «Всадник на белом коне» была издана в 1962 году. Затем я написал повести «Волны» (1963) и «Кому не исполнилось восемнадцати?» (1965).' WHERE id = 2324;
UPDATE fact_cards SET topic_ru = 'Мои сборники рассказов', question_ru = 'Какие сборники рассказов есть у Шукура Холмирзаева?', fact_ru = 'Меня больше знают как рассказчика. Изданы мои сборники рассказов «Под далёкими звёздами» (1971), «Жизнь вечна» (1974), «Если сдвинется тяжёлый камень...» (1980), «Дороги, спутники» (1984).' WHERE id = 2325;
UPDATE fact_cards SET topic_ru = 'Мои романы и драмы', question_ru = 'Какие романы и драмы написал Шукур Холмирзаев?', fact_ru = 'Я написал романы «Последняя остановка» (1976), «Мост-волосок» (1984), «Путник» (1987), «Пугало» (1992), а первая книга моего романа «Динозавр» вышла в 1996 году. Для сцены я создал драмы «Чёрный пояс» (1987) и «Пиршество» (1990).' WHERE id = 2326;
UPDATE fact_cards SET topic_ru = 'Байсун и природа', question_ru = 'Какое место занимает природа в творчестве Шукура Холмирзаева?', fact_ru = 'Взгляните на названия моих произведений: «На горы лёг снег», «Миндаль зацвёл зимою», «Под далёкими звёздами» — горы и камни, природа всегда живут в моих рассказах. Корни этого — в горах моей родины, Байсуна.' WHERE id = 2327;
UPDATE fact_cards SET topic_ru = 'Мои звания и награды', question_ru = 'Какие награды получил Шукур Холмирзаев?', fact_ru = 'В 1989 году я получил республиканскую Государственную премию имени Хамзы. В 1991 году мне было присвоено звание народного писателя Узбекистана, а в 1999 году я был награждён орденом «Мехнат шухрати».' WHERE id = 2328;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Шукур Холмирзаев?', fact_ru = 'Я скончался 29 сентября 2005 года в городе Ташкенте. После меня осталось большое литературное наследие из рассказов, повестей, романов и драм.' WHERE id = 2329;

-- ===== Tog'ay Murod =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Тагай Мурад?', fact_ru = 'Я родился 3 февраля 1948 года в селении Ходжасаат Денауского района Сурхандарьинской области. Моё настоящее имя и фамилия — Менгноров Тагаймурад, а «Тагай Мурад» — мой литературный псевдоним.' WHERE id = 2354;
UPDATE fact_cards SET topic_ru = 'Мой путь учёбы и труда', question_ru = 'Где учился и работал Тагай Мурад?', fact_ru = 'В 1972 году я окончил факультет журналистики Ташкентского государственного университета. Затем работал редактором на республиканском радио (1972–1975), в газете «Физкультурник Узбекистана» (1976–1978) и в журнале «Фан ва турмуш» (1982–1984). В 1984–1986 годах я учился на Высших литературных курсах в Москве.' WHERE id = 2355;
UPDATE fact_cards SET topic_ru = '«Вечер, когда заржал конь»', question_ru = 'Кто и когда написал повесть «Вечер, когда заржал конь»?', fact_ru = 'Свою повесть «Вечер, когда заржал конь» я написал в 1979 году.' WHERE id = 2356;
UPDATE fact_cards SET topic_ru = 'Мои повести', question_ru = 'Какие ещё повести написал Тагай Мурад?', fact_ru = 'Свою первую повесть — «Звёзды горят вечно» — я издал в 1976 году. Затем я написал повести «Люди, идущие в лунном свете» (1980) и «Песнь матери-Земли» (1985).' WHERE id = 2357;
UPDATE fact_cards SET topic_ru = '«Поля, оставшиеся от отца»', question_ru = 'Что известно о романе «Поля, оставшиеся от отца»?', fact_ru = 'В 1993 году я написал свой роман «Поля, оставшиеся от отца». В 2001 году по этому моему роману был снят художественный фильм.' WHERE id = 2358;
UPDATE fact_cards SET topic_ru = 'Мои переводы и мой роман', question_ru = 'Произведения каких писателей переводил Тагай Мурад?', fact_ru = 'Я перевёл на узбекский язык драму и рассказы Джека Лондона «Дочь снегов», а также повесть Э. Сетона-Томпсона «Мустанг-иноходец». Написал я и роман «В этом мире умереть невозможно».' WHERE id = 2359;
UPDATE fact_cards SET topic_ru = 'Мои награды и звания', question_ru = 'Каких наград и званий удостоился Тагай Мурад?', fact_ru = 'За повесть «Люди, идущие в лунном свете» я удостоился премии имени Айбека. В 1994 году за роман «Поля, оставшиеся от отца» я получил Государственную премию имени Абдуллы Кадыри. А в 1999 году мне было присвоено звание «Народный писатель Узбекистана».' WHERE id = 2360;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Тагай Мурад?', fact_ru = 'Я скончался 27 мая 2003 года в городе Ташкенте.' WHERE id = 2361;

-- ===== Muhammad Yusuf =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Мухаммад Юсуф?', fact_ru = 'Я родился 26 апреля 1954 года в Мархаматском районе Андижанской области. Родной мой край Андижан стал одной из главных тем моих стихов.' WHERE id = 2235;
UPDATE fact_cards SET topic_ru = 'Где я учился', question_ru = 'Где учился Мухаммад Юсуф?', fact_ru = 'В 1978 году я окончил Институт русского языка и литературы. Хотя я изучал русскую литературу, стихи свои я писал на родном — узбекском языке.' WHERE id = 2236;
UPDATE fact_cards SET topic_ru = 'Моя первая книга', question_ru = 'Каков первый поэтический сборник Мухаммада Юсуфа?', fact_ru = 'Мой первый поэтический сборник называется «Знакомые тополя», он был издан в 1985 году. После этого вышли мои книги «Есть у меня слово к соловью» (1987) и «Мольба» (1988).' WHERE id = 2237;
UPDATE fact_cards SET topic_ru = 'Мои поэтические сборники', question_ru = 'Какие книги написал Мухаммад Юсуф?', fact_ru = 'Я написал много книг — «Спящая девушка», «Колыбельные матушки Халимы», «Корабль любви», «В сердце моём любимая» и «Резвая лань». Мой сборник «Унесу тебя в моё небо» вышел в 1998 году.' WHERE id = 2238;
UPDATE fact_cards SET topic_ru = 'Мои стихи о Родине', question_ru = 'Что воспевал Мухаммад Юсуф в своих стихах?', fact_ru = 'В своих стихах я воспевал родную Отчизну, матерей и мой трудовой народ. Мои стихи «Моя Родина» и «Матушка» многие помнят наизусть.' WHERE id = 2239;
UPDATE fact_cards SET topic_ru = 'Моя работа в газете', question_ru = 'Где работал Мухаммад Юсуф?', fact_ru = 'Я работал в газете «Тошкент окшоми». Там я служил вместе с моим другом-поэтом Сирожиддином Сайидом.' WHERE id = 2240;
UPDATE fact_cards SET topic_ru = 'Моё звание народного поэта', question_ru = 'Когда Мухаммад Юсуф получил звание народного поэта?', fact_ru = 'В 1998 году мне было присвоено высокое звание «Народный поэт Узбекистана». Это звание стало для меня знаком любви моего народа.' WHERE id = 2241;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Мухаммад Юсуф?', fact_ru = 'Я скончался 31 июля 2001 года в Элликкалинском районе. Я прожил всего 47 лет, но оставил своему народу свои стихи.' WHERE id = 2242;
